package org.sebastiandev.trip.user.messaging; import io.quarkus.hibernate.reactive.panache.Panache; import io.quarkus.scheduler.Scheduled; import io.smallrye.mutiny.Uni; import io.smallrye.reactive.messaging.MutinyEmitter; import io.smallrye.reactive.messaging.kafka.KafkaRecord; import jakarta.enterprise.context.ApplicationScoped; import jakarta.inject.Inject; import java.time.*; import java.util.List; import org.eclipse.microprofile.reactive.messaging.Channel; import org.sebastiandev.trip.user.repository.OutboxRepository;
@ApplicationScoped public class OutboxPublisher{@Inject OutboxRepository repository;@Inject @Channel("outbox")MutinyEmitter<String> emitter;@Scheduled(every="1s",concurrentExecution=Scheduled.ConcurrentExecution.SKIP)Uni<Void> publish(){return repository.find("publishedAt is null order by createdAt").page(0,50).list().chain(this::batch);}private Uni<Void> batch(List<OutboxEvent> events){Uni<Void> chain=Uni.createFrom().voidItem();for(OutboxEvent e:events)chain=chain.chain(()->emitter.sendMessage(KafkaRecord.of(e.topic,e.aggregateId.toString(),e.payload)).chain(()->Panache.withTransaction(()->repository.findById(e.id).invoke(x->{x.publishedAt=OffsetDateTime.now(ZoneOffset.UTC);x.attempts++;})).replaceWithVoid()));return chain;}}
